{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2167-08-19 14:35:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you during this stay. Can you tell me what brought you to the hospital today?"
    },
    {
      "turn_number": 2,
      "time": "2167-08-19 14:36:00",
      "speaker": "Patient",
      "text": "Hi. I’ve had a bad cough with green, sometimes bloody sputum for two days. It hurts to swallow and even to breathe deeply. I couldn’t keep anything down."
    },
    {
      "turn_number": 3,
      "time": "2167-08-19 14:37:00",
      "speaker": "Doctor",
      "text": "I see. And you’ve had this before? Any fever or shortness of breath?"
    },
    {
      "turn_number": 4,
      "time": "2167-08-19 14:38:00",
      "speaker": "Patient",
      "text": "No fever. Same as last time—just pain and trouble swallowing. I’ve been nauseous too."
    },
    {
      "turn_number": 5,
      "time": "2167-08-19 14:39:00",
      "speaker": "Doctor",
      "text": "Okay. We’ve checked your vitals and they’re stable. No fever, and your oxygen is good. We did a chest X-ray—no pneumonia or other lung issues."
    },
    {
      "turn_number": 6,
      "time": "2167-08-19 14:40:00",
      "speaker": "Patient",
      "text": "Is my trach okay? I was worried it might be infected again."
    },
    {
      "turn_number": 7,
      "time": "2167-08-19 14:41:00",
      "speaker": "Doctor",
      "text": "The ENT team scoped it in the ER. The trachea looks normal—no redness, swelling, or pus. So it doesn’t look like active tracheitis this time."
    },
    {
      "turn_number": 8,
      "time": "2167-08-19 14:42:00",
      "speaker": "Patient",
      "text": "But the sputum is still green and thick. Why is that?"
    },
    {
      "turn_number": 9,
      "time": "2167-08-19 14:43:00",
      "speaker": "Doctor",
      "text": "That can happen even without infection, especially with your history. Chronic bronchitis and mucus buildup can cause that. Your white blood cell count is normal, which supports it’s not an active infection."
    },
    {
      "turn_number": 10,
      "time": "2167-08-19 14:44:00",
      "speaker": "Patient",
      "text": "I just want to be able to eat again. I haven’t had anything in two days."
    },
    {
      "turn_number": 11,
      "time": "2167-08-19 14:45:00",
      "speaker": "Doctor",
      "text": "We’re going to help with that. You’re already on your usual meds—lidocaine for throat pain, oxycodone for discomfort, and omeprazole for reflux. We’ll start you on small sips to see how you do."
    },
    {
      "turn_number": 12,
      "time": "2167-08-19 15:10:00",
      "speaker": "Doctor",
      "text": "How are you feeling after trying that water?"
    },
    {
      "turn_number": 13,
      "time": "2167-08-19 15:11:00",
      "speaker": "Patient",
      "text": "It’s still uncomfortable, but I didn’t choke. I think I could try applesauce."
    },
    {
      "turn_number": 14,
      "time": "2167-08-19 15:12:00",
      "speaker": "Doctor",
      "text": "Great. We’ll have the nurse bring some. We also scheduled a swallow study tomorrow to make sure it’s safe."
    },
    {
      "turn_number": 15,
      "time": "2167-08-20 09:15:00",
      "speaker": "Doctor",
      "text": "Good morning. The swallow study was done this morning. You tolerated thin liquids, applesauce, and crackers. No signs of aspiration."
    },
    {
      "turn_number": 16,
      "time": "2167-08-20 09:16:00",
      "speaker": "Patient",
      "text": "But I still feel like food is sticking. Is that normal?"
    },
    {
      "turn_number": 17,
      "time": "2167-08-20 09:17:00",
      "speaker": "Doctor",
      "text": "Yes, that sensation has been consistent over the years. Your anatomy prevents actual aspiration, so it’s safe to eat soft foods. We recommend thin liquids with soft solids, and crushing pills in applesauce."
    },
    {
      "turn_number": 18,
      "time": "2167-08-20 09:18:00",
      "speaker": "Patient",
      "text": "So it’s not getting worse?"
    },
    {
      "turn_number": 19,
      "time": "2167-08-20 09:19:00",
      "speaker": "Doctor",
      "text": "No, it’s stable. The study was similar to past ones. The pain and sensation are likely from inflammation around your trach site and chronic GERD."
    },
    {
      "turn_number": 20,
      "time": "2167-08-20 09:20:00",
      "speaker": "Patient",
      "text": "I’ve been on omeprazole and ranitidine. Should I keep both?"
    },
    {
      "turn_number": 21,
      "time": "2167-08-20 09:21:00",
      "speaker": "Doctor",
      "text": "Yes, we’re keeping both because reflux might be making your throat pain worse. We’ll continue them at home."
    },
    {
      "turn_number": 22,
      "time": "2167-08-20 10:30:00",
      "speaker": "Doctor",
      "text": "Your labs came back. Your hemoglobin is low, around 7.7, but it’s similar to past levels. It’s chronic anemia, so we’re not treating it now—just monitoring."
    },
    {
      "turn_number": 23,
      "time": "2167-08-20 10:31:00",
      "speaker": "Patient",
      "text": "Is that why I feel tired sometimes?"
    },
    {
      "turn_number": 24,
      "time": "2167-08-20 10:32:00",
      "speaker": "Doctor",
      "text": "Possibly. But you’re also dealing with chronic pain and multiple health issues. We’ll make sure your PCP follows up on it."
    },
    {
      "turn_number": 25,
      "time": "2167-08-20 14:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well—eating, no fever, vitals stable. We’re thinking you could go home tomorrow if this continues."
    },
    {
      "turn_number": 26,
      "time": "2167-08-20 14:01:00",
      "speaker": "Patient",
      "text": "That’s good. But what if the pain comes back at home?"
    },
    {
      "turn_number": 27,
      "time": "2167-08-20 14:02:00",
      "speaker": "Doctor",
      "text": "You’ll keep using the viscous lidocaine and oxycodone as needed. But remember, you’re on a narcotic contract, so no extra prescriptions this time."
    },
    {
      "turn_number": 28,
      "time": "2167-08-20 14:03:00",
      "speaker": "Patient",
      "text": "I know. I might have taken a few extra during this flare-up. I’ll check how many I have left and call my PCP."
    },
    {
      "turn_number": 29,
      "time": "2167-08-20 14:04:00",
      "speaker": "Doctor",
      "text": "That’s the right plan. We’ll also recommend follow-up with pain management if needed."
    },
    {
      "turn_number": 30,
      "time": "2167-08-20 15:30:00",
      "speaker": "Doctor",
      "text": "Your mom mentioned you’ve been feeling overwhelmed. Is that something you’d like support with?"
    },
    {
      "turn_number": 31,
      "time": "2167-08-20 15:31:00",
      "speaker": "Patient",
      "text": "Yeah. It’s hard managing everything—my trach, pain, appointments. I get anxious."
    },
    {
      "turn_number": 32,
      "time": "2167-08-20 15:32:00",
      "speaker": "Doctor",
      "text": "We’ve connected you with social work. They can help with coping strategies and resources. And keep seeing your therapist."
    },
    {
      "turn_number": 33,
      "time": "2167-08-21 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—you’re ready to go home today. You’ve been eating well, no pain with breathing, and your trach site looks clean."
    },
    {
      "turn_number": 34,
      "time": "2167-08-21 08:01:00",
      "speaker": "Patient",
      "text": "What should I watch for?"
    },
    {
      "turn_number": 35,
      "time": "2167-08-21 08:02:00",
      "speaker": "Doctor",
      "text": "If you have fevers, trouble breathing, or pus from your trach, come back. For swallowing pain, stick to soft foods, crush pills, and do oral care three times a day."
    },
    {
      "turn_number": 36,
      "time": "2167-08-21 08:03:00",
      "speaker": "Patient",
      "text": "And my meds?"
    },
    {
      "turn_number": 37,
      "time": "2167-08-21 08:04:00",
      "speaker": "Doctor",
      "text": "Same as before—oxycodone and lidocaine for pain, omeprazole and ranitidine for reflux, fluoxetine for mood. Gabapentin is still listed, but you said your PCP stopped it?"
    },
    {
      "turn_number": 38,
      "time": "2167-08-21 08:05:00",
      "speaker": "Patient",
      "text": "Yes, they thought it wasn’t helping. Should I restart it?"
    },
    {
      "turn_number": 39,
      "time": "2167-08-21 08:06:00",
      "speaker": "Doctor",
      "text": "We’ll leave that to your PCP. Mention it at your follow-up. And please keep your ENT appointment—they’ll check your trach."
    },
    {
      "turn_number": 40,
      "time": "2167-08-21 08:07:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better already."
    },
    {
      "turn_number": 41,
      "time": "2167-08-21 08:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and call if anything changes."
    },
    {
      "turn_number": 42,
      "time": "2167-08-21 10:15:00",
      "speaker": "Doctor",
      "text": "Just a quick check before discharge. How’s the pain now?"
    },
    {
      "turn_number": 43,
      "time": "2167-08-21 10:16:00",
      "speaker": "Patient",
      "text": "Much better. I had juice and crackers this morning with no issues."
    },
    {
      "turn_number": 44,
      "time": "2167-08-21 10:17:00",
      "speaker": "Doctor",
      "text": "Excellent. We’ll get your discharge papers ready. Remember—oral care, soft diet, and follow up with your team."
    },
    {
      "turn_number": 45,
      "time": "2167-08-21 10:18:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 46,
      "time": "2167-08-21 10:19:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Have a safe trip home."
    },
    {
      "turn_number": 47,
      "time": "2167-08-21 12:00:00",
      "speaker": "Doctor",
      "text": "Final check—your mom is here, and transport is ready. Any last questions?"
    },
    {
      "turn_number": 48,
      "time": "2167-08-21 12:01:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Thank you for explaining everything."
    },
    {
      "turn_number": 49,
      "time": "2167-08-21 12:02:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Take care and stay in touch with your doctors."
    },
    {
      "turn_number": 50,
      "time": "2167-08-21 12:03:00",
      "speaker": "Patient",
      "text": "I will. See you soon, hopefully not in the hospital!"
    },
    {
      "turn_number": 51,
      "time": "2167-08-21 12:04:00",
      "speaker": "Doctor",
      "text": "Fingers crossed. Have a good one."
    }
  ],
  "summary": {
    "admission_start": "2167-08-19 14:32:00",
    "admission_end": "2167-08-21 18:01:00",
    "summary_paragraph": "A young woman with a history of tracheobronchomalacia and tracheostomy was admitted for cough with green, blood-tinged sputum, throat pain, and inability to tolerate oral intake for two days. She had no fever, stable vital signs, and normal white blood cell count. Imaging showed no acute cardiopulmonary abnormalities, and ENT evaluation found no tracheal inflammation. A swallow study confirmed mild oropharyngeal dysphagia without aspiration, consistent with prior findings. She was managed symptomatically with pain control, dietary modifications, and continuation of home medications. She improved, tolerated oral intake, and was discharged home with instructions for soft diet, oral care, and follow-up with ENT and primary care.",
    "problems": [
      "Pain in throat",
      "Dysphagia, unspecified",
      "Abnormal sputum",
      "Cough",
      "Unspecified asthma, uncomplicated",
      "Other specified diseases of upper respiratory tract",
      "Other diseases of bronchus, not elsewhere classified",
      "Tracheostomy status",
      "Bronchopulmonary dysplasia originating in the perinatal period",
      "Stenosis of larynx",
      "Gastro-esophageal reflux disease without esophagitis",
      "Iron deficiency anemia, unspecified",
      "Major depressive disorder, single episode, unspecified"
    ]
  }
}
